/**
 * ``ExtractedNoteEdit`` — view de edição de uma nota AK. Após salvar
 * ou após reload pós-CAS conflict, navega de volta para
 * ``#/extracted-notes/:id``.
 *
 * Espelha ``NoteEdit`` mas aponta para ``useNote(noteId, "acquire")``
 * e usa as rotas ``extracted-note*``. Sem o adapter correto, o save
 * voltaria 404 do CM; sem as rotas dedicadas, a navegação pós-save
 * cairia em 404 também.
 */

import { useTranslation } from "react-i18next";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { NoteEditor } from "@/components/kg/NoteEditor";
import { useNote } from "@/hooks/useNote";
import { useHashRoute } from "@/hooks/useHashRoute";
import { cn } from "@/lib/utils";

export function ExtractedNoteEdit({ noteId, className }: { noteId: string; className?: string }) {
  const { t } = useTranslation();
  const [, navigate] = useHashRoute();
  const { note, loading, error, refresh, saveBody } = useNote(noteId, "acquire");

  if (loading) return <SurfaceLoadingFallback className={className} />;
  if (error) return <EmptyStateI18n messageKey="errors.network" className={className} />;
  if (!note) return <EmptyStateI18n messageKey="errors.notFound" className={className} />;

  return (
    <div className={cn("h-full min-h-0 overflow-y-auto p-6", className)}>
      <NoteEditor
        note={note}
        onSave={async ({ body, baseBodyHash }) => {
          await saveBody({ body, baseBodyHash });
        }}
        onCancel={() => navigate({ kind: "extracted-note", id: noteId })}
        onSaved={async () => {
          await refresh();
          navigate({ kind: "extracted-note", id: noteId });
        }}
        onReload={async () => {
          await refresh();
          navigate({ kind: "extracted-note", id: noteId });
        }}
      />
      <p className="sr-only">{t("notes.editor.saving")}</p>
    </div>
  );
}