/**
 * ``KgClientProvider`` — provê a URL base do adapter HTTP para os
 * componentes. Pattern idêntico ao ``ClientProvider`` da WebUI
 * (que provê o NanobotClient).
 *
 * Fase 1 / B1: provê também o ``bundle`` ativo (``"cm"`` ou ``"ak"``) e
 * ``setBundle``. Persistido em ``localStorage`` para sobreviver refresh.
 * Default ``"cm"`` preserva comportamento atual.
 *
 * N3 (auditoria #2, 2026-07-31): sincroniza o bundle entre abas via
 * evento ``storage``. Sem isso, trocar de bundle em uma aba não
 * afeta as outras que estão abertas (state diverge silenciosamente).
 */

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from "react";
import { useTranslation } from "react-i18next";
import { resolveApiBase } from "@/lib/bootstrap";
import { setGatewayTransport } from "@/lib/api";
import { GatewayKgTransport, GatewayTransportError } from "@/lib/gateway-transport";

export type Bundle = "cm" | "ak";

const BUNDLE_STORAGE_KEY = "kg-interface.bundle";

function readStoredBundle(): Bundle {
  if (typeof window === "undefined") return "cm";
  try {
    const raw = window.localStorage.getItem(BUNDLE_STORAGE_KEY);
    return raw === "ak" ? "ak" : "cm";
  } catch {
    return "cm";
  }
}

function persistBundle(bundle: Bundle): void {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(BUNDLE_STORAGE_KEY, bundle);
  } catch {
    // ignore
  }
}

interface KgClientContextValue {
  /** URL base do adapter (e.g. ``/kg-interface/api``). */
  apiBase: string;
  /** Bundle ativo na UI (Fase 1 / B1, D52). */
  bundle: Bundle;
  /** Troca o bundle ativo. Persiste em ``localStorage``. */
  setBundle: (bundle: Bundle) => void;
}

const KgClientContext = createContext<KgClientContextValue | null>(null);

export function KgClientProvider({
  apiBase,
  children,
}: {
  apiBase?: string;
  children: ReactNode;
}) {
  const [bundle, setBundleState] = useState<Bundle>(() => readStoredBundle());
  const { t } = useTranslation();
  const resolvedBase = apiBase ?? resolveApiBase();
  const native = apiBase === undefined && resolvedBase === "/kg-interface/api";
  const [credential, setCredential] = useState("");
  const [loginError, setLoginError] = useState(false);
  const [transportState, setTransportState] = useState<"loading" | "ready" | "login" | "error">("loading");
  const transportRef = useRef<GatewayKgTransport | null>(null);

  useEffect(() => {
    if (!native) return;
    let active = true;
    const transport = new GatewayKgTransport(() => {
      if (!active) return;
      setGatewayTransport(null);
      setTransportState("login");
    });
    transportRef.current = transport;
    void transport.ready().then(() => {
      if (!active) return;
      setGatewayTransport(transport);
      setTransportState("ready");
    }).catch((error: unknown) => {
      if (active) {
        setTransportState(error instanceof GatewayTransportError && error.status === 401 ? "login" : "error");
      }
    });
    return () => {
      active = false;
      if (transportRef.current === transport) transportRef.current = null;
      setGatewayTransport(null);
      transport.close();
    };
  }, [native]);

  async function unlock(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const password = credential;
    const transport = transportRef.current;
    if (!password || !transport) return;
    setTransportState("loading");
    setCredential("");
    setLoginError(false);
    try {
      await transport.login(password);
      setGatewayTransport(transport);
      setTransportState("ready");
    } catch {
      setLoginError(true);
      setTransportState("login");
    }
  }

  // Persiste em localStorage; só client-side.
  useEffect(() => {
    persistBundle(bundle);
  }, [bundle]);

  // N3 (auditoria #2): sincroniza bundle entre abas. Quando outra
  // aba chama ``setBundle`` (que persiste em localStorage), o evento
  // ``storage`` dispara **na aba atual** com ``key === BUNDLE_STORAGE_KEY``
  // e ``newValue === "cm"|"ak"``. Atualiza state local para casar.
  // Não atualiza ``newValue=null`` (limpeza de chave) — mantém estado.
  useEffect(() => {
    if (typeof window === "undefined") return;
    function onStorage(e: StorageEvent) {
      if (e.key !== BUNDLE_STORAGE_KEY) return;
      if (e.newValue === null) return; // chave foi removida — ignorar
      const next: Bundle = e.newValue === "ak" ? "ak" : "cm";
      setBundleState((prev) => (prev === next ? prev : next));
    }
    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, []);

  const setBundle = useCallback((next: Bundle) => {
    setBundleState(next);
  }, []);

  const value = useMemo<KgClientContextValue>(
    () => ({ apiBase: resolvedBase, bundle, setBundle }),
    [resolvedBase, bundle, setBundle],
  );
  return <KgClientContext.Provider value={value}>
    {native && transportState !== "ready" ? (
      <main className="flex min-h-screen items-center justify-center p-6">
        {transportState === "loading" ? <p>{t("gatewayLogin.connecting")}</p> : (
          <form onSubmit={unlock} className="flex max-w-sm flex-col gap-3">
            <label htmlFor="kg-gateway-password">{t("gatewayLogin.password")}</label>
            <input id="kg-gateway-password" type="password" autoComplete="current-password" value={credential}
              onChange={(event) => setCredential(event.target.value)} />
            {(loginError || transportState === "error") && <p role="alert">{t("gatewayLogin.error")}</p>}
            <button type="submit" disabled={!credential}>{t("gatewayLogin.submit")}</button>
          </form>
        )}
      </main>
    ) : children}
  </KgClientContext.Provider>;
}

export function useKgClient(): KgClientContextValue {
  const ctx = useContext(KgClientContext);
  if (!ctx) {
    throw new Error("useKgClient must be used within a KgClientProvider");
  }
  return ctx;
}
