/**
 * ``HomeView`` — landing page do shell. Mostra stats resumidos +
 * últimas notas + Available operations (Fase 1 / B8) +
 * Recent writes (Fase 1 / B7).
 *
 * Stats: Fase 1 / B4 usa ``useStatsAll`` (paralelo CM + AK) — stats de
 * AK aparece como card separado se disponível. Default CM-first
 * preserva comportamento histórico.
 *
 * Refactor visual 2026-08-08: hierarquia + ícones + agrupamento. As
 * mudanças são puramente cosméticas — comportamento e dados
 * consumidos continuam idênticos.
 *   - 3 stat cards no topo (Notes / Sources / Extracted) com ícone
 *   - ícones nos títulos de seção para escaneabilidade
 *   - "Available operations" agrupado semanticamente em 4 colunas
 *     (Read / Edit / Search & viz / Delegate) com ícone por grupo
 *   - max-w-6xl mx-auto para não esticar em monitores ultrawide
 *   - gap-8 entre seções (antes gap-6) para mais respiro
 */

import { useTranslation } from "react-i18next";
import {
  Brain,
  FileText,
  Layers,
  Sprout,
  PencilLine,
  BookOpen,
  Pencil,
  Compass,
  Bot,
} from "lucide-react";
import { NoteCard } from "@/components/kg/NoteCard";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";
import { useStatsAll } from "@/hooks/useStats";
import { useNotes } from "@/hooks/useNotes";
import { useSources } from "@/hooks/useSources";
import { useHashRoute } from "@/hooks/useHashRoute";
import { cn } from "@/lib/utils";

export function HomeView({ className }: { className?: string }) {
  const { t } = useTranslation();
  const { memory, acquire, memoryLoading } = useStatsAll();
  const { notes, loading: notesLoading } = useNotes({ limit: 6 });
  const { sources } = useSources();
  const [, navigate] = useHashRoute();

  // H1 (bugfix-spa-2026-08-02): antes o guard era ``loading ||
  // notesLoading``, com ``loading`` agregando CM **e** AK. Com AK down, o
  // fetch de AK só falha no timeout de 20s — e a Home ficava em skeleton
  // esse tempo todo mesmo já tendo stats de CM e a lista de notas em
  // mãos. Agora só mostramos skeleton enquanto NÃO há absolutamente nada
  // para renderizar; assim que qualquer lado chega, a Home aparece e as
  // seções sem dados se resolvem sozinhas (``{memory && …}``,
  // ``{acquire && …}``, EmptyState das notas).
  const nothingToShow = memory === null && notes.length === 0;
  if (nothingToShow && (memoryLoading || notesLoading)) {
    return <SurfaceLoadingFallback className={className} />;
  }

  return (
    <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-8 overflow-y-auto p-6 md:p-8", className)}>
      {/* Header — ícone + título + subtitle em uma linha mais limpa */}
      <header className="flex flex-col gap-1">
        <h1 className="flex items-center gap-2 text-2xl font-semibold">
          <Brain className="h-5 w-5 text-muted-foreground" aria-hidden />
          {t("home.title")}
        </h1>
        {memory && (
          <p className="text-sm text-muted-foreground">
            {t("home.subtitle", {
              count: memory.notes_total,
              sources: sources.length,
            })}
            {acquire && acquire.notes_total > 0 && (
              <>
                {" · "}
                {t("home.subtitleAK", { count: acquire.notes_total })}
              </>
            )}
          </p>
        )}
      </header>

      {!memory && !memoryLoading && (
        <p role="alert" className="rounded-md border border-amber-500/40 bg-amber-500/5 p-3 text-sm">
          {t("home.memoryUnavailable")}
        </p>
      )}

      {/* Stat cards — 3 colunas com ícone, número grande, label pequeno */}
      {memory && <section className="grid grid-cols-1 gap-3 sm:grid-cols-3">
        <StatCard
          icon={<FileText className="h-4 w-4" aria-hidden />}
          value={memory.notes_total}
          label={t("stats.notes")}
          tone="default"
        />
        <StatCard
          icon={<Layers className="h-4 w-4" aria-hidden />}
          value={acquire ? sources.length : "—"}
          label={t("stats.sources")}
          tone="default"
        />
        <StatCard
          icon={<Sprout className="h-4 w-4" aria-hidden />}
          value={acquire?.notes_total ?? "—"}
          label={t("stats.akNotes")}
          tone={acquire ? "default" : "muted"}
        />
      </section>}

      {memory?.recent_writes && memory.recent_writes.length > 0 && (
        <section>
          <SectionHeader icon={<PencilLine className="h-4 w-4" aria-hidden />}>
            {t("home.recentWrites")}
          </SectionHeader>
          <ul className="flex flex-col gap-1.5 text-sm">
            {memory.recent_writes.slice(0, 5).map((w) => (
              <li
                key={w.id}
                className="group flex items-center justify-between gap-2 rounded-md border-l-2 border-primary/40 bg-card px-3 py-1.5 transition-colors hover:bg-accent/40"
              >
                <button
                  type="button"
                  onClick={() => navigate({ kind: "note", id: w.id, query: new URLSearchParams() })}
                  className="truncate text-left font-mono text-xs text-primary hover:underline"
                  title={w.path}
                >
                  {w.path}
                </button>
                <time className="shrink-0 text-xs tabular-nums text-muted-foreground">
                  {new Date(w.modified_at).toLocaleString()}
                </time>
              </li>
            ))}
          </ul>
        </section>
      )}

      <section>
        <SectionHeader icon={<FileText className="h-4 w-4" aria-hidden />}>
          {t("home.recentNotes")}
        </SectionHeader>
        {notes.length === 0 ? (
          <EmptyStateI18n messageKey={memory ? "home.emptyRecent" : "home.memoryUnavailable"} />
        ) : (
          <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">
            {notes.map((note) => (
              <NoteCard key={note.id} note={note} />
            ))}
          </div>
        )}
      </section>

      <section className="rounded-lg border border-border bg-card/50 p-4">
        <SectionHeader icon={<BookOpen className="h-4 w-4" aria-hidden />}>
          {t("home.availableOperations")}
        </SectionHeader>
        <div className="grid grid-cols-1 gap-4 text-sm sm:grid-cols-2 lg:grid-cols-4">
          <OpsGroup
            title={t("home.opsGroups.read")}
            icon={<BookOpen className="h-3.5 w-3.5" aria-hidden />}
            items={[t("home.ops.readNotes"), t("home.ops.readSources"), t("home.ops.browseChunks")]}
          />
          <OpsGroup
            title={t("home.opsGroups.edit")}
            icon={<Pencil className="h-3.5 w-3.5" aria-hidden />}
            items={[t("home.ops.editBody"), t("home.ops.archiveNotes")]}
          />
          <OpsGroup
            title={t("home.opsGroups.search")}
            icon={<Compass className="h-3.5 w-3.5" aria-hidden />}
            items={[t("home.ops.searchBoth"), t("home.ops.viewGraph")]}
          />
          <OpsGroup
            title={t("home.opsGroups.delegate")}
            icon={<Bot className="h-3.5 w-3.5" aria-hidden />}
            items={[t("home.ops.delegate")]}
            muted
          />
        </div>
      </section>
    </div>
  );
}

// ---------- Sub-componentes locais ----------

/** Cabeçalho de seção com ícone + título — usado pelas 3 seções
 *  ("Recent writes", "Recent notes", "Available operations"). */
function SectionHeader({
  icon,
  children,
}: {
  icon: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <h2 className="mb-3 flex items-center gap-2 text-sm font-medium text-muted-foreground">
      {icon}
      {children}
    </h2>
  );
}

/** Card de estatística — número grande com label pequeno + ícone. */
function StatCard({
  icon,
  value,
  label,
  tone,
}: {
  icon: React.ReactNode;
  value: number | string;
  label: string;
  tone: "default" | "muted";
}) {
  return (
    <div
      className={cn(
        "flex items-center gap-3 rounded-lg border border-border bg-card p-4 transition-colors",
        tone === "muted" && "opacity-60",
      )}
    >
      <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-md bg-accent text-accent-foreground">
        {icon}
      </div>
      <div className="min-w-0">
        <div className="text-2xl font-semibold tabular-nums leading-tight">{value}</div>
        <div className="text-xs text-muted-foreground truncate">{label}</div>
      </div>
    </div>
  );
}

/** Grupo de operações disponíveis — título + ícone + lista de bullets. */
function OpsGroup({
  title,
  icon,
  items,
  muted,
}: {
  title: string;
  icon: React.ReactNode;
  items: string[];
  muted?: boolean;
}) {
  return (
    <div className="flex flex-col gap-1.5">
      <div
        className={cn(
          "flex items-center gap-1.5 text-xs font-medium uppercase tracking-wide",
          muted ? "text-muted-foreground" : "text-foreground",
        )}
      >
        {icon}
        {title}
      </div>
      <ul className="flex flex-col gap-1 text-sm">
        {items.map((item) => (
          <li
            key={item}
            className={cn(
              "flex gap-2",
              muted ? "text-muted-foreground" : "text-foreground/90",
            )}
          >
            <span aria-hidden className="select-none">·</span>
            <span>{item}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}
