/**
 * ``NotesList`` — listagem filtrada de notas com search.
 *
 * Refactor visual 2026-08-08: header com ícone + subtítulo com contagem
 * (``count`` do payload — pode ser > ``notes.length`` se o servidor
 * limitar a página). max-w-6xl / gap-3 / md:p-8 mantêm o padrão do
 * HomeView/StatsView.
 */

import { useState } from "react";
import { useTranslation } from "react-i18next";
import { Search, FileText } from "lucide-react";
import { Input } from "@/components/ui/input";
import { NoteCard } from "@/components/kg/NoteCard";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";
import { useNotes } from "@/hooks/useNotes";
import { cn } from "@/lib/utils";

export function NotesList({ className }: { className?: string }) {
  const { t } = useTranslation();
  const [q, setQ] = useState("");
  // ``count`` é o total no servidor (não trunca em 200 — usado no subtitle
  // para o humano saber o tamanho real do conjunto filtrado).
  const { notes, count, loading, error } = useNotes({ q, limit: 200 });

  return (
    <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-6 overflow-y-auto p-6 md:p-8", className)}>
      <header className="flex flex-col gap-1">
        <h1 className="flex items-center gap-2 text-2xl font-semibold">
          <FileText className="h-5 w-5 text-muted-foreground" aria-hidden />
          {t("notes.title")}
        </h1>
        {!loading && (
          <p className="text-sm text-muted-foreground">
            {q
              ? t("notes.subtitleFiltered", { count, q })
              : t("notes.subtitle", { count })}
          </p>
        )}
      </header>
      <div className="relative">
        <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" aria-hidden />
        <Input
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder={t("notes.searchPlaceholder")}
          className="pl-9"
        />
      </div>

      {loading ? (
        <SurfaceLoadingFallback />
      ) : error ? (
        <EmptyStateI18n messageKey={error.includes("HTTP 503") ? "graph.bundleUnavailable"
          : error.includes("HTTP 403") ? "errors.forbidden" : "errors.network"} />
      ) : notes.length === 0 ? (
        <EmptyStateI18n messageKey="notes.empty" />
      ) : (
        <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">
          {notes.map((note) => (
            <NoteCard key={note.id} note={note} />
          ))}
        </div>
      )}
    </div>
  );
}
