/**
 * ``useNotes`` — lista notas com refresh opcional. Pattern idêntico
 * ao ``useSessions`` da WebUI: state local + ``useEffect`` + ``refresh``.
 *
 * A dependência do useCallback usa ``options.q`` e ``options.limit`` em
 * vez de ``options`` (object identity) — chamar ``useNotes({ q: "x" })``
 * toda render gera novo objeto mas os mesmos primitivos, evitando
 * loop de fetch+rerender+refetch.
 *
 * Bug SPA-R2-9 (revisão 2): o antigo não tinha debounce em ``q``,
 * então cada keystroke na ``NotesList`` disparava um fetch contra o
 * servidor. UX ruim em links lentos e desperdício de CPU/battery. O
 * ``useSearch`` já fazia debounce desde o início (200ms); aplicando
 * aqui o mesmo padrão — pequeno conserto que unifica o comportamento
 * dos dois hooks de listagem.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { listNotes, ApiError } from "@/lib/api";
import { useKgClient } from "@/providers/KgClientProvider";
import type { NoteListItem } from "@/lib/types";

const DEBOUNCE_MS = 200;

export interface UseNotesResult {
  notes: NoteListItem[];
  /** Total real no servidor (``count`` do payload), pode ser > ``notes.length``
   *  quando ``limit`` limita a página. 0 enquanto carregando. */
  count: number;
  loading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
}

export function useNotes(options: { q?: string; limit?: number } = {}): UseNotesResult {
  const { apiBase } = useKgClient();
  const rawQ = options.q;
  const limit = options.limit;
  const [notes, setNotes] = useState<NoteListItem[]>([]);
  const [count, setCount] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  // ``q`` interno debounced — derivamos da prop ``rawQ``. O fetch
  // efetivo só acontece após DEBOUNCE_MS sem mudança. Mantemos a
  // prop externa ``options.q`` como fonte de verdade (componente
  // pai não precisa saber sobre debounce).
  const [debouncedQ, setDebouncedQ] = useState(rawQ ?? "");
  useEffect(() => {
    const next = rawQ ?? "";
    if (next === debouncedQ) return;
    const t = setTimeout(() => setDebouncedQ(next), DEBOUNCE_MS);
    return () => clearTimeout(t);
  }, [rawQ, debouncedQ]);
  // Contador de geração, não boolean — ver comentário equivalente em
  // ``useNote.ts``. Aqui importa ainda mais: ``q`` muda a cada tecla
  // digitada em ``NotesList``, então requests concorrentes são o caso
  // comum, não a exceção — uma resposta antiga chegando fora de
  // ordem não pode vencer uma mais nova.
  const requestIdRef = useRef(0);

  const refresh = useCallback(async () => {
    const requestId = ++requestIdRef.current;
    setLoading(true);
    try {
      const data = await listNotes(apiBase, { q: debouncedQ, limit });
      if (requestIdRef.current !== requestId) return;
      setNotes(data.results);
      setCount(data.count);
      setError(null);
    } catch (e) {
      if (requestIdRef.current !== requestId) return;
      setError(e instanceof ApiError ? `HTTP ${e.status}` : (e as Error).message);
    } finally {
      if (requestIdRef.current === requestId) setLoading(false);
    }
  }, [apiBase, debouncedQ, limit]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  return { notes, count, loading, error, refresh };
}