/**
 * ``StatsView`` — view de stats rica (collective-memory + acquire-knowledge).
 *
 * Fase 1 / B4 usa ``useStatsAll`` (paralelo CM + AK). Refactor visual
 * 2026-08-08 adiciona cobertura derivada, atomização de sources, e
 * breakdown por media_type — todos os campos já estavam no payload,
 * só não eram exibidos.
 *
 * Layout em 3 zonas:
 *   1. Knowledge — coverage + graph health + tags + types + orphans/untriaged
 *   2. Sources — atomization + breakdown por media_type
 *   3. Activity — recent writes (já aparecia na Home; aqui também)
 *
 * ``useSources`` retorna SourceListItem[] com chunks_total/chunks_atomized/
 * size_bytes — agrega-se client-side (sem chamada adicional).
 */

import { useEffect, useMemo, useState } from "react";
import { useTranslation } from "react-i18next";
import {
  ChevronDown,
  ChevronRight,
  BarChart3,
  Network,
  Tags,
  Shapes,
  Inbox,
  Link2,
  Files,
  FolderOpen,
  ListChecks,
  Activity,
  AlertCircle,
} from "lucide-react";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { Badge } from "@/components/kg/Badge";
import { useStatsAll } from "@/hooks/useStats";
import { useSources } from "@/hooks/useSources";
import { useHashRoute } from "@/hooks/useHashRoute";
import { useKgClient } from "@/providers/KgClientProvider";
import { repoMaintenance, storageStats } from "@/lib/api";
import { Button } from "@/components/ui/button";
import type { MaintenanceResult, StorageSummary } from "@/lib/types";
import { cn } from "@/lib/utils";

export function StatsView({ className }: { className?: string }) {
  const { t } = useTranslation();
  const { memory, acquire, memoryLoading, error } = useStatsAll();
  const { sources } = useSources();
  const [, navigate] = useHashRoute();
  const [orphansOpen, setOrphansOpen] = useState(false);
  const [untriagedOpen, setUntriagedOpen] = useState(false);
  // P11
  const [reviewOpen, setReviewOpen] = useState(false);
  const { apiBase } = useKgClient();
  const [storage, setStorage] = useState<StorageSummary | null>(null);
  const [maintBusy, setMaintBusy] = useState(false);
  const [maintResult, setMaintResult] = useState<MaintenanceResult | null>(null);

  // Storage vem de uma chamada própria (``/storage/stats``) em vez de vir
  // no ``/stats``: a varredura de ``.git`` custa mais que todo o resto do
  // stats somado, e nem toda navegação precisa dela.
  useEffect(() => {
    let cancelled = false;
    void storageStats(apiBase)
      .then((s) => {
        if (!cancelled) setStorage(s);
      })
      .catch(() => {
        // Storage é informativo — falhar aqui não pode derrubar a tela
        // inteira de stats.
        if (!cancelled) setStorage(null);
      });
    return () => {
      cancelled = true;
    };
  }, [apiBase]);

  async function runMaintenance(): Promise<void> {
    setMaintBusy(true);
    try {
      const res = await repoMaintenance(apiBase, false);
      setMaintResult(res);
      setStorage(await storageStats(apiBase));
    } catch {
      setMaintResult(null);
    } finally {
      setMaintBusy(false);
    }
  }
  const [recentOpen, setRecentOpen] = useState(true);

  // Todos os hooks ficam ANTES dos early returns (regra de hooks).
  // ``useMemo`` com dependência ``memory`` simplesmente roda com
  // undefined enquanto CM não respondeu — não há problema.

  const topTags = useMemo(
    () =>
      memory
        ? Object.entries(memory.tags_distribution)
            .sort((a, b) => b[1] - a[1])
            .slice(0, 10)
        : [],
    [memory],
  );

  const types = useMemo(
    () =>
      memory
        ? Object.entries(memory.types_distribution).sort((a, b) => b[1] - a[1])
        : [],
    [memory],
  );

  // Coverage: % de notas com tags / com type / com backlinks. Notes_total
  // é a base; backlinked = total - orphans (proxy conservadora).
  const coverage = useMemo(() => {
    const total = memory?.notes_total || 1;
    const taggedCount = memory
      ? Math.min(
          Object.values(memory.tags_distribution).reduce((a, b) => a + b, 0),
          total,
        )
      : 0;
    const typedCount = memory
      ? Math.min(
          Object.values(memory.types_distribution).reduce((a, b) => a + b, 0),
          total,
        )
      : 0;
    const backlinkedCount = memory
      ? Math.max(total - memory.orphans.length, 0)
      : 0;
    return {
      tagged: Math.round((taggedCount / total) * 100),
      typed: Math.round((typedCount / total) * 100),
      backlinked: Math.round((backlinkedCount / total) * 100),
    };
  }, [memory]);

  // Sources: agrega chunks_total, chunks_atomized, size_bytes,
  // conta por media_type, e lista partial.
  const sourcesAgg = useMemo(() => {
    const byMediaType: Record<string, number> = {};
    let chunksTotal = 0;
    let chunksAtomized = 0;
    let sizeBytes = 0;
    let partiallyAtomized = 0;
    for (const s of sources) {
      const mt = s.media_type ?? "unknown";
      byMediaType[mt] = (byMediaType[mt] ?? 0) + 1;
      chunksTotal += s.chunks_total ?? 0;
      chunksAtomized += s.chunks_atomized?.length ?? 0;
      sizeBytes += s.size_bytes ?? 0;
      if (s.partially_atomized) partiallyAtomized += 1;
    }
    return {
      total: sources.length,
      chunksTotal,
      chunksAtomized,
      coverage: chunksTotal > 0 ? Math.round((chunksAtomized / chunksTotal) * 100) : 0,
      sizeMb: sizeBytes / (1024 * 1024),
      partiallyAtomized,
      byMediaType: Object.entries(byMediaType).sort((a, b) => b[1] - a[1]),
    };
  }, [sources]);

  // M1 — só mostrar skeleton enquanto CM não respondeu; AK chega depois
  // sem bloquear a renderização principal.
  if (memoryLoading) return <SurfaceLoadingFallback className={className} />;
  if (error || !memory) return <EmptyStateI18n messageKey={error?.includes("HTTP 503")
    ? "graph.bundleUnavailable" : error?.includes("HTTP 403") ? "errors.forbidden" : "errors.network"} className={className} />;

  const graph = memory.graph_health ?? null;
  const recent = memory.recent_writes ?? [];

  return (
    <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-8 overflow-y-auto p-6 md:p-8", className)}>
      {/* Header */}
      <header className="flex flex-col gap-1">
        <h1 className="flex items-center gap-2 text-2xl font-semibold">
          <BarChart3 className="h-5 w-5 text-muted-foreground" aria-hidden />
          {t("stats.title")}
        </h1>
        <p className="text-sm text-muted-foreground">
          {t("stats.subtitle", {
            notes: memory.notes_total,
            sources: sourcesAgg.total,
          })}
        </p>
      </header>

      {/* Top stat strip — 3 cards grandes */}
      <section className="grid grid-cols-2 gap-3 md:grid-cols-3">
        <BigStat
          icon={<Files className="h-5 w-5" aria-hidden />}
          value={memory.notes_total}
          label={t("stats.notes")}
        />
        <BigStat
          icon={<FolderOpen className="h-5 w-5" aria-hidden />}
          value={sourcesAgg.total}
          label={t("stats.sources")}
        />
        {acquire ? (
          <BigStat
            icon={<ListChecks className="h-5 w-5" aria-hidden />}
            value={acquire.notes_total}
            label={t("stats.akNotes")}
          />
        ) : (
          <BigStat
            icon={<ListChecks className="h-5 w-5" aria-hidden />}
            value={0}
            label={t("stats.akNotes")}
            muted
          />
        )}
      </section>

      {/* ─── Knowledge section ─── */}
      <SectionHeading icon={<Network className="h-4 w-4" aria-hidden />}>
        {t("stats.sections.knowledge")}
      </SectionHeading>

      {/* Coverage */}
      <section>
        <h3 className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">
          {t("stats.coverage.title")}
        </h3>
        <div className="grid grid-cols-1 gap-3 md:grid-cols-3">
          <CoverageBar
            icon={<Tags className="h-3.5 w-3.5" aria-hidden />}
            label={t("stats.coverage.tagged")}
            percent={coverage.tagged}
          />
          <CoverageBar
            icon={<Shapes className="h-3.5 w-3.5" aria-hidden />}
            label={t("stats.coverage.typed")}
            percent={coverage.typed}
          />
          <CoverageBar
            icon={<Link2 className="h-3.5 w-3.5" aria-hidden />}
            label={t("stats.coverage.backlinked")}
            percent={coverage.backlinked}
          />
        </div>
      </section>

      {/* Graph health */}
      <section>
        <h3 className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">
          {t("stats.graph.title")}
        </h3>
        <div className="rounded-lg border border-border bg-card p-4">
          {graph && (graph.nodes !== undefined || graph.edges !== undefined) ? (
            <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-sm">
              <GraphStat
                icon={<Network className="h-3.5 w-3.5" aria-hidden />}
                label={t("stats.graph.nodes")}
                value={graph.nodes ?? 0}
              />
              <GraphStat
                icon={<Activity className="h-3.5 w-3.5" aria-hidden />}
                label={t("stats.graph.edges")}
                value={graph.edges ?? 0}
              />
              <div className="flex items-center gap-2 text-muted-foreground">
                <span className="font-medium">{t("stats.graph.lastBuild")}:</span>
                <span className="tabular-nums">
                  {graph.last_build
                    ? new Date(graph.last_build).toLocaleString()
                    : t("stats.graph.never")}
                </span>
              </div>
            </div>
          ) : (
            <p className="flex items-center gap-2 text-sm text-muted-foreground">
              <AlertCircle className="h-3.5 w-3.5" aria-hidden />
              {t("stats.graph.empty")}
            </p>
          )}
        </div>
      </section>

      {/* Top tags + Note types em 2 colunas */}
      <section className="grid grid-cols-1 gap-4 md:grid-cols-2">
        <DistributionCard
          icon={<Tags className="h-4 w-4" aria-hidden />}
          title={t("stats.tags")}
          entries={topTags}
          empty={t("home.emptyRecent")}
          variant="secondary"
        />
        <DistributionCard
          icon={<Shapes className="h-4 w-4" aria-hidden />}
          title={t("stats.types")}
          entries={types}
          empty={t("home.emptyRecent")}
          variant="outline"
        />
      </section>

      {/* Orphans + Untriaged collapsibles */}
      <section className="grid grid-cols-1 gap-3 md:grid-cols-2">
        <CollapsibleList
          icon={<AlertCircle className="h-3.5 w-3.5 text-amber-500" aria-hidden />}
          title={t("stats.orphans")}
          count={memory.orphans.length}
          open={orphansOpen}
          onToggle={() => setOrphansOpen((v) => !v)}
          items={memory.orphans}
          empty={t("stats.noOrphans")}
          onItemClick={(id) => navigate({ kind: "note", id, query: new URLSearchParams() })}
        />
        <CollapsibleList
          icon={<Inbox className="h-3.5 w-3.5 text-muted-foreground" aria-hidden />}
          title={t("stats.untriaged")}
          count={memory.untriaged_inbox.length}
          open={untriagedOpen}
          onToggle={() => setUntriagedOpen((v) => !v)}
          items={memory.untriaged_inbox}
          empty={t("stats.noUntriaged")}
          onItemClick={(id) => navigate({ kind: "note", id, query: new URLSearchParams() })}
        />
      </section>

      {/* ─── P11: fila de revisão + policy ─── */}
      <section className="grid grid-cols-1 gap-3 md:grid-cols-2">
        <CollapsibleList
          icon={<AlertCircle className="h-3.5 w-3.5 text-destructive" aria-hidden />}
          title={t("stats.pendingReview")}
          count={memory.flagged_count}
          open={reviewOpen}
          onToggle={() => setReviewOpen((v) => !v)}
          items={memory.pending_review_ids}
          empty={t("stats.noPendingReview")}
          onItemClick={(id) => navigate({ kind: "note", id, query: new URLSearchParams() })}
        />
        <div className="rounded-lg border border-border bg-card p-4">
          <h3 className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
            {t("stats.policy.title")}
          </h3>
          <dl className="mt-2 space-y-1 text-sm">
            <div className="flex justify-between">
              <dt className="text-muted-foreground">{t("stats.policy.protected")}</dt>
              <dd className="tabular-nums">{memory.protected_count}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-muted-foreground">{t("stats.policy.cold")}</dt>
              <dd className="tabular-nums">{memory.cold_count}</dd>
            </div>
          </dl>
        </div>
      </section>

      {/* ─── P11: storage ─── */}
      {storage ? (
        <section className="rounded-lg border border-border bg-card p-4">
          <div className="flex items-baseline justify-between">
            <h3 className="text-xs font-medium uppercase tracking-wide text-muted-foreground">
              {t("stats.storage.title")}
            </h3>
            <Badge
              variant={
                storage.status === "critical"
                  ? "destructive"
                  : storage.status === "warning"
                    ? "default"
                    : "secondary"
              }
            >
              {t(`stats.storage.status.${storage.status}`)}
            </Badge>
          </div>

          <p className="mt-2 text-sm">
            {t("stats.storage.total", { size: formatBytes(storage.total_bytes) })}
          </p>

          {/* Breakdown por diretório. ``.git`` aparece aqui de propósito:
              costuma ser a maior fatia, e uma medição que só olhasse
              ``notes/`` reportaria "ok" enquanto o disco enche. */}
          <dl className="mt-3 space-y-1 text-sm">
            {Object.entries(storage.by_dir).map(([dir, usage]) => (
              <div key={dir} className="flex items-baseline justify-between gap-2">
                <dt className="font-mono text-xs text-muted-foreground">{dir}</dt>
                <dd className="tabular-nums">
                  {formatBytes(usage.bytes)}
                  {usage.cold !== undefined ? (
                    <span className="ml-2 text-xs text-muted-foreground">
                      {t("stats.storage.activeCold", {
                        active: usage.active ?? 0,
                        cold: usage.cold,
                      })}
                    </span>
                  ) : null}
                </dd>
              </div>
            ))}
          </dl>

          {/* A ação que de fato libera espaço. Sem frase de confirmação:
              ``git gc`` não reescreve histórico nem remove nota alguma. */}
          {storage.maintenance.recommended ? (
            <div className="mt-3 rounded-md border border-amber-500/50 bg-amber-500/5 p-3">
              <p className="text-sm">{storage.maintenance.hint}</p>
              <p className="mt-1 text-xs text-muted-foreground">
                {t("stats.storage.reclaimable", {
                  size: formatBytes(storage.maintenance.estimated_reclaimable_bytes),
                })}
              </p>
              <Button
                size="sm"
                className="mt-2"
                disabled={maintBusy}
                onClick={() => void runMaintenance()}
              >
                {maintBusy ? t("stats.storage.running") : t("stats.storage.runMaintenance")}
              </Button>
            </div>
          ) : null}

          {maintResult ? (
            <p className="mt-2 text-xs text-muted-foreground" role="status">
              {t("stats.storage.reclaimed", {
                size: formatBytes(Math.max(maintResult.reclaimed_bytes, 0)),
              })}
            </p>
          ) : null}
        </section>
      ) : null}

      {/* ─── Sources section ─── */}
      {sourcesAgg.total > 0 && (
        <>
          <SectionHeading icon={<FolderOpen className="h-4 w-4" aria-hidden />}>
            {t("stats.sections.sources")}
          </SectionHeading>

          <section>
            <h3 className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">
              {t("stats.sourcesDetail.atomization")}
            </h3>
            <div className="rounded-lg border border-border bg-card p-4">
              <div className="flex items-baseline justify-between text-sm">
                <span className="font-medium tabular-nums">
                  {t("stats.sourcesDetail.atomizedOf", {
                    done: sourcesAgg.chunksAtomized,
                    total: sourcesAgg.chunksTotal,
                  })}
                </span>
                <span className="tabular-nums text-muted-foreground">
                  {sourcesAgg.coverage}%
                </span>
              </div>
              <div className="mt-2 h-2 overflow-hidden rounded-full bg-muted">
                <div
                  className="h-full bg-primary transition-[width]"
                  style={{ width: `${sourcesAgg.coverage}%` }}
                  role="progressbar"
                  aria-valuenow={sourcesAgg.coverage}
                  aria-valuemin={0}
                  aria-valuemax={100}
                />
              </div>
              <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground">
                <span>{t("stats.sourcesDetail.chunksTotal", { count: sourcesAgg.chunksTotal })}</span>
                {sourcesAgg.partiallyAtomized > 0 && (
                  <span>
                    {t("stats.sourcesDetail.partiallyAtomized", {
                      count: sourcesAgg.partiallyAtomized,
                    })}
                  </span>
                )}
                <span>{sourcesAgg.sizeMb.toFixed(1)} MB</span>
              </div>
            </div>
          </section>

          {sourcesAgg.byMediaType.length > 0 && (
            <section>
              <h3 className="mb-2 text-xs font-medium uppercase tracking-wide text-muted-foreground">
                {t("stats.sourcesDetail.byMediaType")}
              </h3>
              <div className="flex flex-wrap gap-1.5">
                {sourcesAgg.byMediaType.map(([mt, count]) => (
                  <Badge key={mt} variant="outline">
                    {mt} · {count}
                  </Badge>
                ))}
              </div>
            </section>
          )}
        </>
      )}

      {/* ─── Activity section ─── */}
      <SectionHeading icon={<Activity className="h-4 w-4" aria-hidden />}>
        {t("stats.sections.activity")}
      </SectionHeading>

      {/* Bugfix 2026-08-08: a versão anterior reusava ``CollapsibleList``
          com ``onItemClick={() => {}}`` (no-op) porque a navegação
          "não parecia útil" — recent writes mostrava paths, não ids.
          Mas ``RecentWrite`` tem ``id``/``path``/``modified_at`` e
          cliclar DEVE abrir a nota (mesma ação que nos Recent Notes
          da Home). Aqui cada item é renderizado com botão que
          navega para ``#/notes/:id``. */}
      <RecentWritesList
        writes={recent}
        open={recentOpen}
        onToggle={() => setRecentOpen((v) => !v)}
        onOpen={(id) => navigate({ kind: "note", id, query: new URLSearchParams() })}
      />
    </div>
  );
}

/** Versão especializada de CollapsibleList para Recent writes.
 *  Navega para ``#/notes/:id`` ao clicar (RecentWrite.id vem do
 *  payload de ``/memory/stats``). Render condicional baseado em
 *  ``writes.length`` para evitar o cabeçalho "Recent writes (0)"
 *  sempre visível. */
function RecentWritesList({
  writes,
  open,
  onToggle,
  onOpen,
}: {
  writes: ReadonlyArray<{ id: string; path: string; modified_at: string }>;
  open: boolean;
  onToggle: () => void;
  onOpen: (id: string) => void;
}) {
  // Hooks ANTES de qualquer early return — regra do React.
  const { t } = useTranslation();
  if (writes.length === 0) {
    // Sem recent writes — não mostra a seção toda (silêncio > ruído).
    return null;
  }
  return (
    <section className="rounded-lg border border-border bg-card">
      <button
        type="button"
        onClick={onToggle}
        className="flex w-full items-center gap-2 px-4 py-3 text-left text-sm font-medium text-muted-foreground hover:text-foreground"
        aria-expanded={open}
      >
        {open ? <ChevronDown className="h-3.5 w-3.5" /> : <ChevronRight className="h-3.5 w-3.5" />}
        <Activity className="h-3.5 w-3.5 text-muted-foreground" aria-hidden />
        {t("home.recentWrites")}{" "}
        <span className="font-mono tabular-nums">({writes.length})</span>
      </button>
      {open && (
        <div className="max-h-60 overflow-y-auto border-t border-border px-4 py-2 text-xs">
          <ul className="flex flex-col gap-1">
            {writes.map((w) => (
              <li key={w.id} className="font-mono">
                <button
                  type="button"
                  onClick={() => onOpen(w.id)}
                  className="flex w-full items-center justify-between gap-2 truncate text-left text-primary hover:underline"
                  title={w.path}
                >
                  <span className="truncate">{w.path}</span>
                  <time className="shrink-0 text-xs tabular-nums text-muted-foreground">
                    {new Date(w.modified_at).toLocaleString()}
                  </time>
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </section>
  );
}

// ---------- Sub-componentes locais ----------

function SectionHeading({
  icon,
  children,
}: {
  icon: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <h2 className="flex items-center gap-2 border-t border-border pt-6 text-sm font-medium uppercase tracking-wide text-muted-foreground">
      {icon}
      {children}
    </h2>
  );
}

/** Stat card grande no topo (ícone + número + label). */
function BigStat({
  icon,
  value,
  label,
  muted,
}: {
  icon: React.ReactNode;
  value: number;
  label: string;
  muted?: boolean;
}) {
  return (
    <div
      className={cn(
        "flex items-center gap-3 rounded-lg border border-border bg-card p-4",
        muted && "opacity-60",
      )}
    >
      <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-md bg-accent text-accent-foreground">
        {icon}
      </div>
      <div className="min-w-0">
        <div className="text-2xl font-semibold tabular-nums leading-tight">{value}</div>
        <div className="text-xs text-muted-foreground truncate">{label}</div>
      </div>
    </div>
  );
}

/** Barra de cobertura — label + % + barra horizontal fina. */
function CoverageBar({
  icon,
  label,
  percent,
}: {
  icon: React.ReactNode;
  label: string;
  percent: number;
}) {
  return (
    <div className="rounded-lg border border-border bg-card p-3">
      <div className="flex items-center justify-between text-sm">
        <span className="flex items-center gap-1.5 font-medium">
          {icon}
          {label}
        </span>
        <span className="tabular-nums text-muted-foreground">{percent}%</span>
      </div>
      <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-muted">
        <div
          className="h-full bg-primary transition-[width]"
          style={{ width: `${percent}%` }}
          role="progressbar"
          aria-valuenow={percent}
          aria-valuemin={0}
          aria-valuemax={100}
        />
      </div>
    </div>
  );
}

/** Stat pequeno inline para o graph health (sem card wrapper). */
function GraphStat({
  icon,
  label,
  value,
}: {
  icon: React.ReactNode;
  label: string;
  value: number | string;
}) {
  return (
    <span className="inline-flex items-center gap-1.5">
      {icon}
      <span className="text-muted-foreground">{label}:</span>
      <span className="font-medium tabular-nums">{value}</span>
    </span>
  );
}

/** Card com distribuição (tags ou types) — badges com count. */
function DistributionCard({
  icon,
  title,
  entries,
  empty,
  variant,
}: {
  icon: React.ReactNode;
  title: string;
  entries: Array<[string, number]>;
  empty: string;
  variant: "secondary" | "outline";
}) {
  return (
    <div className="rounded-lg border border-border bg-card p-4">
      <h3 className="mb-3 flex items-center gap-2 text-sm font-medium text-muted-foreground">
        {icon}
        {title}
      </h3>
      {entries.length === 0 ? (
        <p className="text-xs text-muted-foreground">{empty}</p>
      ) : (
        <div className="flex flex-wrap gap-1.5">
          {entries.map(([name, count]) => (
            <Badge key={name} variant={variant}>
              {name} · {count}
            </Badge>
          ))}
        </div>
      )}
    </div>
  );
}

/** Lista colapsável genérica com clique opcional nos items. */
function CollapsibleList({
  icon,
  title,
  count,
  open,
  onToggle,
  items,
  empty,
  onItemClick,
  renderItem,
}: {
  icon?: React.ReactNode;
  title: string;
  count: number;
  open: boolean;
  onToggle: () => void;
  items: string[];
  empty: string;
  onItemClick?: (item: string) => void;
  renderItem?: (item: string) => React.ReactNode;
}) {
  return (
    <section className="rounded-lg border border-border bg-card">
      <button
        type="button"
        onClick={onToggle}
        className="flex w-full items-center gap-2 px-4 py-3 text-left text-sm font-medium text-muted-foreground hover:text-foreground"
        aria-expanded={open}
      >
        {open ? <ChevronDown className="h-3.5 w-3.5" /> : <ChevronRight className="h-3.5 w-3.5" />}
        {icon}
        {title} <span className="font-mono tabular-nums">({count})</span>
      </button>
      {open && (
        <div className="max-h-60 overflow-y-auto border-t border-border px-4 py-2 text-xs">
          {items.length === 0 ? (
            <p className="py-1 text-muted-foreground">{empty}</p>
          ) : (
            <ul className="flex flex-col gap-1">
              {items.map((item) => (
                <li key={item} className="font-mono">
                  {onItemClick ? (
                    <button
                      type="button"
                      onClick={() => onItemClick(item)}
                      className="truncate text-left text-primary hover:underline w-full"
                      title={item}
                    >
                      {renderItem ? renderItem(item) : item}
                    </button>
                  ) : (
                    renderItem ? renderItem(item) : item
                  )}
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </section>
  );
}

/**
 * Bytes → string legível. Base 1024 com sufixos SI curtos, que é a
 * convenção que o ``du -h`` usa e com a qual o operador vai comparar.
 */
function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes <= 0) return "0 B";
  const units = ["B", "KB", "MB", "GB", "TB"];
  const exp = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
  const value = bytes / Math.pow(1024, exp);
  return `${value.toFixed(exp === 0 ? 0 : 1)} ${units[exp]}`;
}
