/**
 * ``useSources`` — lista Sources com refresh.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { listSources, ApiError } from "@/lib/api";
import { useKgClient } from "@/providers/KgClientProvider";
import type { SourceListItem } from "@/lib/types";

export function useSources(): {
  sources: SourceListItem[];
  loading: boolean;
  error: string | null;
  refresh: () => Promise<void>;
} {
  const { apiBase } = useKgClient();
  const [sources, setSources] = useState<SourceListItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  // Bug SPA-2/4 (revisão): ``cancelledRef`` boolean é resetado para
  // false a cada ``refresh``, então uma resposta ANTIGA chegando
  // DEPOIS de uma ``refresh`` mais nova pode sobrescrever o estado.
  // Contador de geração resolve — cada ``refresh`` captura o id e só
  // aplica o resultado se for o mais recente. Mesma correção do
  // ``useNote.ts`` / ``useNotes.ts``.
  const requestIdRef = useRef(0);

  const refresh = useCallback(async () => {
    const requestId = ++requestIdRef.current;
    setLoading(true);
    try {
      const data = await listSources(apiBase, { limit: 200 });
      if (requestIdRef.current !== requestId) return;
      setSources(data.results);
      setError(null);
    } catch (e) {
      if (requestIdRef.current !== requestId) return;
      setError(e instanceof ApiError ? `HTTP ${e.status}` : (e as Error).message);
    } finally {
      if (requestIdRef.current === requestId) setLoading(false);
    }
  }, [apiBase]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  return { sources, loading, error, refresh };
}
