/** Native graph visualization using the gateway's authenticated NetworkX node-link data. */
import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { ArrowRight, Brain, Clock, HardDrive, Layers, Link2, Network } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { BundleSelector } from "@/components/layout/BundleSelector";
import { GraphCanvas } from "@/components/kg/GraphCanvas";
import { SurfaceLoadingFallback } from "@/components/kg/SurfaceLoadingFallback";
import { EmptyStateI18n } from "@/components/kg/EmptyState";
import { ApiError, graph, graphData } from "@/lib/api";
import { useKgClient } from "@/providers/KgClientProvider";
import { useStatsAll } from "@/hooks/useStats";
import { useHashRoute } from "@/hooks/useHashRoute";
import { formatRelativeTime } from "@/lib/format";
import type { GraphData, GraphResponse } from "@/lib/types";
import { cn } from "@/lib/utils";

export function GraphView({ className }: { className?: string }) {
  const { t } = useTranslation();
  const { apiBase, bundle } = useKgClient();
  const [, navigate] = useHashRoute();
  const [metadata, setMetadata] = useState<GraphResponse | null>(null);
  const [data, setData] = useState<GraphData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [errorCode, setErrorCode] = useState<string | null>(null);
  const [jumpId, setJumpId] = useState("");
  const requestIdRef = useRef(0);
  const { memory, acquire } = useStatsAll();
  const bundleStats = bundle === "ak" ? acquire : memory;
  const graphHealth = bundleStats?.graph_health ?? null;
  const adapter = bundle === "ak" ? "acquire" : "memory";

  useEffect(() => {
    const requestId = ++requestIdRef.current;
    setMetadata(null);
    setData(null);
    setError(null);
    setErrorCode(null);
    setLoading(true);
    void graph(apiBase, adapter).then(async (result) => {
      if (requestIdRef.current !== requestId) return;
      setMetadata(result);
      if (result.status === "invalid") {
        setErrorCode("graph_invalid");
      } else if (result.exists && result.status !== "stale") {
        const payload = await graphData(apiBase, adapter);
        if (requestIdRef.current === requestId) setData(payload);
      } else if (result.status === "stale") {
        setErrorCode("graph_stale");
      }
    }).catch((reason: unknown) => {
      if (requestIdRef.current !== requestId) return;
      setError(reason instanceof ApiError ? `HTTP ${reason.status}` : String(reason));
      if (reason instanceof ApiError && typeof reason.detail === "object" && reason.detail !== null
        && "error" in reason.detail && typeof reason.detail.error === "string") {
        setErrorCode(reason.detail.error);
      }
    }).finally(() => {
      if (requestIdRef.current === requestId) setLoading(false);
    });
    return () => { ++requestIdRef.current; };
  }, [apiBase, adapter]);

  const openNode = (node: { id: string; type?: string }) => {
    navigate({
      kind: bundle === "ak" ? (node.type === "Source" ? "source" : "extracted-note") : "note",
      id: node.id,
      query: new URLSearchParams(),
    });
  };

  if (loading) return <div className={className}><BundleSelector className="m-6" /><SurfaceLoadingFallback /></div>;
  if (error) return <div className={cn("p-6", className)}><BundleSelector className="mb-4" />
    <p role="alert">{t(errorCode === "bundle_uninitialized" || errorCode === "native_disabled"
      ? "graph.bundleUnavailable" : "errors.network")}{errorCode ? "" : `: ${error}`}</p></div>;
  if (errorCode === "graph_invalid" || errorCode === "graph_stale") return <div className={cn("p-6", className)}>
    <h1 className="mb-6 flex items-center gap-2 text-2xl font-semibold"><Brain aria-hidden />{t("graph.title")}</h1>
    <BundleSelector className="mb-4" />
    <p role="alert">{t(errorCode === "graph_stale" ? "graph.stale" : "graph.invalid")}</p>
  </div>;
  if (!metadata?.exists || !data?.nodes.length) return <div className={cn("p-6", className)}>
    <h1 className="mb-6 flex items-center gap-2 text-2xl font-semibold"><Brain aria-hidden />{t("graph.title")}</h1>
    <BundleSelector className="mb-4" />
    <EmptyStateI18n messageKey={metadata?.exists === false ? (bundleStats?.notes_total ? "graph.notGenerated" : "graph.empty") : "graph.empty"} />
  </div>;

  return <div className={cn("mx-auto flex h-full w-full max-w-6xl flex-col gap-4 p-6 md:p-8", className)}>
    <header className="flex items-center justify-between gap-3">
      <div>
        <h1 className="flex items-center gap-2 text-2xl font-semibold"><Brain className="h-5 w-5" aria-hidden />{t("graph.title")}</h1>
        <p className="text-sm text-muted-foreground">{t("graph.subtitle", { nodes: data.nodes.length, edges: data.links.length })}</p>
      </div>
      <BundleSelector />
    </header>
    <div className="flex items-center gap-2 rounded-md border border-border bg-card px-3 py-2">
      <Input value={jumpId} onChange={(event) => setJumpId(event.target.value)}
        onKeyDown={(event) => { if (event.key === "Enter" && jumpId.trim()) openNode({ id: jumpId.trim() }); }}
        placeholder={t("graph.jumpPlaceholder")} aria-label={t("graph.jumpPlaceholder")}
        className="h-7 flex-1 border-0 bg-transparent px-1 text-xs shadow-none" />
      <Button variant="ghost" size="sm" disabled={!jumpId.trim()}
        onClick={() => openNode({ id: jumpId.trim() })}>
        <ArrowRight className="mr-1 h-3.5 w-3.5" aria-hidden />{t("graph.jumpAction")}
      </Button>
    </div>
    <div className="min-h-0 flex-1 overflow-hidden rounded-md border border-border bg-card">
      <GraphCanvas data={data} onSelect={openNode} />
    </div>
    <dl className="flex flex-wrap items-center gap-x-5 gap-y-2 rounded-md border border-primary/30 bg-card px-4 py-3 text-sm shadow-sm">
      <StatusItem icon={<Network />} label={t("graph.status.nodes")} value={data.nodes.length} />
      <StatusItem icon={<Link2 />} label={t("graph.status.edges")} value={data.links.length} />
      <StatusItem icon={<Clock />} label={t("graph.status.lastBuild")}
        value={graphHealth?.last_build ? formatRelativeTime(graphHealth.last_build) : t("graph.status.never")} />
      <StatusItem icon={<HardDrive />} label={t("graph.status.size")}
        value={`${Math.round(metadata.size_bytes / 1024)} KB`} />
      <StatusItem icon={<Layers />} label={t("graph.status.bundle")}
        value={t(bundle === "ak" ? "bundle.ak" : "bundle.cm")} />
      <span className="ml-auto font-mono text-xs text-muted-foreground/80" title={metadata.path}>{metadata.path}</span>
    </dl>
  </div>;
}

function StatusItem({ icon, label, value }: { icon: React.ReactNode; label: string; value: string | number }) {
  return <span className="inline-flex items-center gap-1">
    <span className="h-4 w-4 [&>svg]:h-4 [&>svg]:w-4">{icon}</span>
    <span className="font-medium text-foreground/80">{label}:</span>
    <span className="font-mono tabular-nums">{value}</span>
  </span>;
}
