/**
 * ``useHashRoute`` — assina mudanças de ``window.location.hash`` e
 * devolve a rota atual + setter. Pattern idêntico ao ``useSessions``
 * da WebUI: state local + ``hashchange`` event listener.
 */

import { useCallback, useEffect, useState } from "react";
import { readRoute, writeRoute, type Route, type RouteKind } from "@/lib/hash-route";

export function useHashRoute(): [Route, (next: Route, options?: { replace?: boolean }) => void] {
  const [route, setRoute] = useState<Route>(() => readRoute());

  useEffect(() => {
    const handler = () => {
      setRoute(readRoute());
    };
    window.addEventListener("hashchange", handler);
    return () => window.removeEventListener("hashchange", handler);
  }, []);

  const navigate = useCallback((next: Route, options?: { replace?: boolean }) => {
    writeRoute(next, options);
    setRoute(next);
  }, []);

  return [route, navigate];
}

export type { RouteKind };
