/**
 * i18next setup. Mesma estrutura da WebUI, mas namespaces
 * ``common`` + ``kg`` (a WebUI tem channel-plugins adicionais que
 * a SPA não usa).
 */

import i18n from "i18next";
import { initReactI18next } from "react-i18next";

import enCommon from "./locales/en/common.json";
import ptBRCommon from "./locales/pt-BR/common.json";
import zhCNCommon from "./locales/zh-CN/common.json";
import zhTWCommon from "./locales/zh-TW/common.json";
import frCommon from "./locales/fr/common.json";
import jaCommon from "./locales/ja/common.json";
import koCommon from "./locales/ko/common.json";
import esCommon from "./locales/es/common.json";
import viCommon from "./locales/vi/common.json";
import idCommon from "./locales/id/common.json";

import {
  applyDocumentLocale,
  defaultLocale,
  fallbackLocale,
  LOCALE_STORAGE_KEY,
  normalizeLocale,
  persistLocale,
  resolveInitialLocale,
  type SupportedLocale,
} from "./config";

export const resources = {
  en: { common: enCommon },
  "pt-BR": { common: ptBRCommon },
  "zh-CN": { common: zhCNCommon },
  "zh-TW": { common: zhTWCommon },
  fr: { common: frCommon },
  ja: { common: jaCommon },
  ko: { common: koCommon },
  es: { common: esCommon },
  vi: { common: viCommon },
  id: { common: idCommon },
} as const;

export function currentLocale(): SupportedLocale {
  return normalizeLocale(i18n.resolvedLanguage ?? i18n.language ?? defaultLocale);
}

export async function setAppLanguage(locale: SupportedLocale): Promise<void> {
  await i18n.changeLanguage(locale);
}

const syncLocaleSideEffects = (language: string) => {
  const locale = normalizeLocale(language);
  applyDocumentLocale(locale);
  persistLocale(locale);
};

// Handler registrado ANTES do init para não perder o ``languageChanged``
// emitido pelo i18n durante a resolução de ``lng`` (e.g. quando
// ``fallbackLng`` é acionado por locale desconhecido).
i18n.on("languageChanged", syncLocaleSideEffects);

if (!i18n.isInitialized) {
  // O ``init`` é async mas não precisamos segurar o carregamento do
  // módulo — o React Suspense + re-render em useTranslation pegam o
  // estado pós-resolved. Importante: NÃO chamar ``syncLocaleSideEffects``
  // aqui no top-level (antes do .then): ``resolvedLanguage`` ainda é
  // ``undefined`` (default) e isso sobrescreveria o localStorage com
  // ``en`` antes do init ler o locale stored. O handler
  // ``languageChanged`` (registrado acima) cobre o caso de mudança de
  // idioma explicitamente. O side-effect inicial é disparado pelo
  // ``init`` quando ``lng=resolveInitialLocale()`` resolve — o handler
  // ``languageChanged`` é chamado e persiste o locale resolvido.
  void i18n
    .use(initReactI18next)
    .init({
      resources,
      lng: resolveInitialLocale(),
      fallbackLng: fallbackLocale,
      defaultNS: "common",
      ns: ["common"],
      interpolation: {
        escapeValue: false,
      },
      returnNull: false,
      supportedLngs: Object.keys(resources),
    });
}

export { LOCALE_STORAGE_KEY };
export default i18n;