/**
 * ``LanguageSwitcher`` — dropdown para trocar de locale. Pattern
 * idêntico ao da WebUI.
 */

import { useTranslation } from "react-i18next";
import { Languages } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { setAppLanguage } from "@/i18n";
import {
  supportedLocales,
  normalizeLocale,
} from "@/i18n/config";

export function LanguageSwitcher() {
  const { t, i18n } = useTranslation();
  // ``resolvedLanguage`` é a fonte de verdade (já passou por
  // ``fallbackLng`` + ``supportedLngs``), mas i18n pode devolver
  // ``"cimode"`` ou outro identificador interno em cenários estranhos.
  // ``normalizeLocale`` garante que ``current`` seja sempre uma chave
  // em ``supportedLocales`` — sem isso, um locale não-suportado
  // passaria pelo cast ``as SupportedLocale`` (Bug SPA-7, revisão) e
  // seria posteriormente persisido no localStorage via
  // ``syncLocaleSideEffects``, deixando a app sem fallback.
  const current = normalizeLocale(i18n.resolvedLanguage ?? i18n.language);
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="icon" aria-label={t("common.language")}>
          <Languages className="h-4 w-4" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {supportedLocales.map((locale) => (
          <DropdownMenuItem
            key={locale.code}
            onClick={() => void setAppLanguage(locale.code)}
            className={locale.code === current ? "font-semibold" : undefined}
          >
            {locale.nativeLabel}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
