/**
 * Types do payload REST do P6 (percival-collective-memory +
 * percival-acquire-knowledge). Schemas Zod + tipos TS derivados.
 *
 * Manter sincronizado com:
 *  - https://github.com/bill-kopp-ai-dev/percival-collective-memory
 *    src/percival_collective_memory/http_server.py
 *  - https://github.com/bill-kopp-ai-dev/percival-acquire-knowledge
 *    src/percival_acquire_knowledge/http_server.py
 *
 * Antes da promoção (2026-08-06), esses arquivos viviam lado a
 * lado no monorepo ``mcp-servers-percival``. O contrato continua
 * o mesmo — só a URL mudou. Quem editar um lado deve editar o
 * outro. Em CI, o ``contract test`` (B7) detecta drift.
 */

import { z } from "zod";

// ---------- Notes (Pydantic ZettelFrontmatter tipado) ----------

// ---------- P11: review / lifecycle ----------

/**
 * Entrada da fila de revisão (``ReviewEntry`` no core).
 *
 * ``kind`` e ``related_actions`` são `z.string()` de propósito, e não
 * `z.enum(...)`: o backend valida contra um `Literal` Pydantic e rejeita o
 * desconhecido antes de persistir. Se a UI *também* enumerasse, um kind
 * novo lançado pelo servidor quebraria a tela inteira até o próximo deploy
 * do frontend — a UI ficaria mais estrita que a fonte da verdade. Aqui
 * preferimos renderizar o kind cru a não renderizar nada.
 */
export const ReviewEntrySchema = z
  .object({
    status: z.enum(["pending", "acknowledged", "resolved"]),
    kind: z.string(),
    confidence: z.enum(["low", "medium", "high"]),
    reason: z.string(),
    flagged_at: z.string(),
    flagged_by: z.string(),
    related_actions: z.array(z.string()).default([]),
    reopened_at: z.string().nullable().optional(),
  })
  .passthrough();
export type ReviewEntry = z.infer<typeof ReviewEntrySchema>;

export const LifecycleSchema = z.enum(["active", "cold"]);
export type Lifecycle = z.infer<typeof LifecycleSchema>;

export const NoteFrontmatterSchema = z
  .object({
    id: z.string().optional(),
    type: z.string().optional(),
    title: z.string().optional(),
    tags: z.array(z.string()).optional(),
    derived_from: z.array(z.string()).optional(),
    // P11 — todos com default para notas legadas (o bundle inteiro é
    // legado hoje: nenhuma das 286 notas tem esses campos).
    protected: z.boolean().default(false),
    lifecycle: LifecycleSchema.default("active"),
    cooled_at: z.string().nullable().optional(),
    review: z.array(ReviewEntrySchema).default([]),
    // P3 collective-memory fields
    created: z.string().optional(),
    updated: z.string().optional(),
    // P5 acquire-knowledge Source fields
    source_kind: z.string().optional(),
    media_type: z.string().optional(),
    size_bytes: z.number().optional(),
    chunks_total: z.number().optional(),
    chunks_atomized: z.array(z.number()).optional(),
  })
  .passthrough();

export type NoteFrontmatter = z.infer<typeof NoteFrontmatterSchema>;

// ---------- Note listing (collective-memory) ----------

export const NoteListItemSchema = z.object({
  id: z.string(),
  path: z.string(),
  title: z.string().nullable().optional(),
  type: z.string().nullable().optional(),
  tags: z.array(z.string()).default([]),
  // P11 — o listing devolve o suficiente para os badges do card sem
  // precisar de um round-trip por nota.
  //
  // ``.optional()`` e não ``.default()``: um hit de ``/search`` vira um
  // ``NoteCard`` pelo mesmo caminho, e ele legitimamente NÃO conhece o
  // estado de lifecycle da nota (a busca não parseia frontmatter). Dar
  // default aqui obrigaria o SearchView a inventar ``protected: false``
  // para notas que podem estar protegidas — o card mentiria.
  protected: z.boolean().optional(),
  lifecycle: LifecycleSchema.optional(),
  pending_review_count: z.number().optional(),
}).passthrough();
export type NoteListItem = z.infer<typeof NoteListItemSchema>;

export const NoteListResponseSchema = z.object({
  results: z.array(NoteListItemSchema),
  count: z.number(),
}).passthrough();
export type NoteListResponse = z.infer<typeof NoteListResponseSchema>;

// ---------- Note read (collective-memory) ----------

export const NoteReadResponseSchema = z.object({
  id: z.string(),
  path: z.string(),
  frontmatter: NoteFrontmatterSchema,
  body: z.string(),
  content_hash: z.string(),
  body_hash: z.string(),
  backlinks: z.array(z.string()).default([]),
}).passthrough();
export type NoteReadResponse = z.infer<typeof NoteReadResponseSchema>;

// ---------- Note write body (CAS) ----------

// Limite de 2 MiB no body — defesa contra DoS no cliente (mesma
// correção já aplicada nos servidores CM + AK na 2ª rodada deles).
// Sem esse limite, um usuário malicioso (ou um caller buggado) pode
// serializar um arquivo arbitrariamente grande e deixar o server
// alocar tudo na memória. Notas reais raramente passam de centenas
// de KiB; 2 MiB é uma margem generosa (10× uma nota grande).
// ``min_length=1`` evita body vazio no front (não diverge com
// okf-bundle-core que já exige body não-vazio via ``write_atomic``).
export const WRITE_BODY_MAX_BYTES = 2 * 1024 * 1024;

export const WriteBodyRequestSchema = z.object({
  body: z.string().min(1).max(WRITE_BODY_MAX_BYTES),
  base_body_hash: z.string().regex(/^[0-9a-f]{64}$/),
  reason: z.string().default("edit body"),
}).passthrough();
export type WriteBodyRequest = z.infer<typeof WriteBodyRequestSchema>;

export const WriteResultResponseSchema = z.object({
  id: z.string(),
  path: z.string(),
  content_hash: z.string(),
  body_hash: z.string(),
  frontmatter: NoteFrontmatterSchema,
}).passthrough();
export type WriteResultResponse = z.infer<typeof WriteResultResponseSchema>;

// ---------- Note history (git log) ----------

export const CommitEntrySchema = z.object({
  sha: z.string(),
  author: z.string(),
  email: z.string(),
  timestamp: z.string(),
  message: z.string(),
  paths: z.array(z.string()),
}).passthrough();
export type CommitEntry = z.infer<typeof CommitEntrySchema>;

export const NoteHistoryResponseSchema = z.object({
  id: z.string(),
  history: z.array(CommitEntrySchema),
}).passthrough();
export type NoteHistoryResponse = z.infer<typeof NoteHistoryResponseSchema>;

// ---------- Search (collective-memory) ----------

// M8 (bugfix-spa-2026-08-02): ``type`` era só ``.optional()`` aqui,
// enquanto o MESMO campo em ``NoteListItemSchema`` é
// ``.nullable().optional()``. Um hit com ``"type": null`` (nota sem
// ``type`` no frontmatter, serializado explicitamente pelo backend)
// reprovava no Zod e virava ``ApiContractError`` — derrubando a
// resposta de busca INTEIRA para ``errors.network``, não só aquele hit.
// Alinhado com ``NoteListItemSchema``; ``NoteCard``/``SourceCard`` já
// tratam ``type`` ausente (``{note.type && <Badge/>}``).
export const SearchHitSchema = z.object({
  id: z.string(),
  path: z.string(),
  title: z.string().nullable().optional(),
  type: z.string().nullable().optional(),
  score: z.number().optional(),
  tags: z.array(z.string()).default([]),
}).passthrough();
export type SearchHit = z.infer<typeof SearchHitSchema>;

export const SearchResponseSchema = z.object({
  results: z.array(SearchHitSchema),
  count: z.number(),
}).passthrough();
export type SearchResponse = z.infer<typeof SearchResponseSchema>;

// ---------- Stats (collective-memory) ----------

// ``RecentWriteSchema`` adicionado na Fase 1 (B7) — W1 F3 do CM devolve
// as últimas 5 escritas no payload de ``/memory/stats``. Antes desta
// fase o Zod descartava silenciosamente o campo (comportamento
// ``strip`` default), escondendo a feature da UI.
export const RecentWriteSchema = z.object({
  id: z.string(),
  path: z.string(),
  modified_at: z.string(),
});
export type RecentWrite = z.infer<typeof RecentWriteSchema>;

// ---------- P11: storage ----------

export const DirUsageSchema = z
  .object({
    count: z.number().optional(),
    bytes: z.number().default(0),
    // ``notes/`` traz o split de lifecycle.
    active: z.number().optional(),
    cold: z.number().optional(),
    // ``graphify-out/`` é artefato regenerável — a UI pode oferecer limpeza
    // sem assustar.
    regenerable: z.boolean().optional(),
    by_month: z
      .array(
        z
          .object({
            month: z.string(),
            count: z.number(),
            bytes: z.number(),
            age_days: z.number().nullable().optional(),
          })
          .passthrough(),
      )
      .optional(),
    oldest_month: z.string().nullable().optional(),
  })
  .passthrough();

/**
 * Estado do repositório git e se vale compactar.
 *
 * É o bloco que aponta para a ação que de fato libera espaço. Medido no
 * bundle real: `.git` com 2945 objetos soltos e zero packs ocupava 16 MB;
 * após `git gc`, 1,6 MB — sem reescrever histórico e preservando todos os
 * commits.
 */
export const MaintenanceInfoSchema = z
  .object({
    loose_objects: z.number().default(0),
    loose_bytes: z.number().default(0),
    packs: z.number().default(0),
    recommended: z.boolean().default(false),
    hint: z.string().default(""),
    estimated_reclaimable_bytes: z.number().default(0),
  })
  .passthrough();
export type MaintenanceInfo = z.infer<typeof MaintenanceInfoSchema>;

export const StorageSummarySchema = z
  .object({
    total_bytes: z.number(),
    status: z.enum(["ok", "warning", "critical"]),
    by_dir: z.record(z.string(), DirUsageSchema).default({}),
    maintenance: MaintenanceInfoSchema,
    thresholds: z.record(z.string(), z.number()).default({}),
  })
  .passthrough();
export type StorageSummary = z.infer<typeof StorageSummarySchema>;

/** Resultado de ``PUT /notes/{id}/protected``. */
export const ProtectedResultSchema = z
  .object({
    id: z.string(),
    protected: z.boolean(),
    changed: z.boolean(),
    cas_matched: z.boolean().optional(),
    content_hash: z.string().optional(),
  })
  .passthrough();
export type ProtectedResult = z.infer<typeof ProtectedResultSchema>;

/** Resultado de ``PUT /notes/{id}/lifecycle``. */
export const LifecycleResultSchema = z
  .object({
    id: z.string(),
    lifecycle: LifecycleSchema,
    cooled_at: z.string().nullable().optional(),
    changed: z.boolean(),
    cas_matched: z.boolean().optional(),
    content_hash: z.string().optional(),
  })
  .passthrough();
export type LifecycleResult = z.infer<typeof LifecycleResultSchema>;

/** Resultado de ``POST /notes/{id}/flag``. ``applied: false`` é sucesso —
 * significa "sinal repetido sem escalada", não erro. */
export const FlagResultSchema = z
  .object({
    id: z.string(),
    applied: z.boolean(),
    kind: z.string(),
    confidence: z.string().optional(),
    existing_confidence: z.string().optional(),
    existing_status: z.string().optional(),
    reason: z.string().optional(),
    review: z.array(ReviewEntrySchema).optional(),
  })
  .passthrough();
export type FlagResult = z.infer<typeof FlagResultSchema>;

export const ReviewResolutionSchema = z.enum([
  "acknowledge",
  "resolve_keep",
  "resolve_cold",
  "resolve_forget",
  "reopen",
]);
export type ReviewResolution = z.infer<typeof ReviewResolutionSchema>;

/** Resultado de ``POST /notes/{id}/resolve``. */
export const ResolveResultSchema = z
  .object({
    id: z.string(),
    kind: z.string(),
    resolution: ReviewResolutionSchema,
    status: z.string(),
    side_effect: z.unknown().nullable().optional(),
  })
  .passthrough();
export type ResolveResult = z.infer<typeof ResolveResultSchema>;

export const MaintenanceResultSchema = z
  .object({
    dry_run: z.boolean(),
    before_bytes: z.number().default(0),
    after_bytes: z.number().default(0),
    reclaimed_bytes: z.number().default(0),
    packs_after: z.number().optional(),
    loose_after: z.number().optional(),
    backend: z.string().nullable().optional(),
    estimated_reclaimable_bytes: z.number().optional(),
  })
  .passthrough();
export type MaintenanceResult = z.infer<typeof MaintenanceResultSchema>;

export const StatsResponseSchema = z.object({
  notes_total: z.number(),
  orphans: z.array(z.string()).default([]),
  untriaged_inbox: z.array(z.string()).default([]),
  tags_distribution: z.record(z.string(), z.number()).default({}),
  types_distribution: z.record(z.string(), z.number()).default({}),
  graph_health: z
    .union([
      z.object({
        nodes: z.number().optional(),
        edges: z.number().optional(),
        last_build: z.string().nullable().optional(),
      }).passthrough(),
      z.null(),
    ])
    .default({}),
  recent_writes: z.array(RecentWriteSchema).default([]),
  // ---------- P11 ----------
  protected_count: z.number().default(0),
  cold_count: z.number().default(0),
  flagged_count: z.number().default(0),
  flagged_by_kind: z.record(z.string(), z.number()).default({}),
  pending_review_ids: z.array(z.string()).default([]),
  // Só vem quando o caller pede ``include_storage`` — a varredura de
  // ``.git`` custa mais que todo o resto do stats somado.
  storage_summary: StorageSummarySchema.nullable().default(null),
}).passthrough();
export type StatsResponse = z.infer<typeof StatsResponseSchema>;

// ---------- Graph metadata ----------

export const GraphResponseSchema = z.union([
  z.object({ exists: z.literal(false), status: z.enum(["missing", "valid", "stale", "invalid"]).optional() }).passthrough(),
  z.object({
    exists: z.literal(true),
    status: z.enum(["missing", "valid", "stale", "invalid"]).optional(),
    path: z.string(),
    size_bytes: z.number(),
  }).passthrough(),
]);
export type GraphResponse = z.infer<typeof GraphResponseSchema>;

/** NetworkX node-link data emitted by the native graph builder. */
export const GraphDataSchema = z.object({
  nodes: z.array(z.object({ id: z.string(), label: z.string().optional() }).passthrough()),
  links: z.array(z.object({ source: z.string(), target: z.string(), relation: z.string().optional() }).passthrough()),
}).passthrough();
export type GraphData = z.infer<typeof GraphDataSchema>;

// ---------- Sources (acquire-knowledge) ----------

export const SourceListItemSchema = z.object({
  id: z.string(),
  path: z.string(),
  title: z.string().nullable().optional(),
  source_kind: z.string().optional(),
  media_type: z.string().optional(),
  size_bytes: z.number().optional(),
  chunks_total: z.number().optional(),
  chunks_atomized: z.array(z.number()).optional(),
  partially_atomized: z.boolean().optional(),
  tags: z.array(z.string()).default([]),
}).passthrough();
export type SourceListItem = z.infer<typeof SourceListItemSchema>;

export const SourceListResponseSchema = z.object({
  results: z.array(SourceListItemSchema),
  count: z.number(),
}).passthrough();
export type SourceListResponse = z.infer<typeof SourceListResponseSchema>;

export const ChunkResponseSchema = z.object({
  source_id: z.string(),
  chunk_index: z.number(),
  text: z.string(),
  locator: z.string().optional(),
  char_count: z.number().optional(),
}).passthrough();
export type ChunkResponse = z.infer<typeof ChunkResponseSchema>;

export const SourceReadResponseSchema = z.object({
  id: z.string(),
  frontmatter: NoteFrontmatterSchema,
  first_chunk: z.object({
    chunk_index: z.number(),
    text: z.string(),
    locator: z.string().optional(),
    char_count: z.number().optional(),
  }).passthrough(),
}).passthrough();
export type SourceReadResponse = z.infer<typeof SourceReadResponseSchema>;

// ---------- Adapter health (drives Sources card visibility) ----------

export const HealthResponseSchema = z.object({
  ok: z.literal(true),
  server: z.string(),
}).passthrough();
export type HealthResponse = z.infer<typeof HealthResponseSchema>;
