/**
 * ``NoteCard`` — card de uma nota (listagem ou preview).
 * Padrão visual consistente com a WebUI (mesma fonte, mesmo
 * Card do shadcn, mesmo muted/foreground).
 *
 * Aceita ``adapter`` (default ``"memory"``): notas do AK
 * (``"acquire"``) precisam apontar para a rota ``extracted-note``
 * (não ``note``), que é resolvida pelo adapter correto do lado do
 * ``NoteView``. Antes desta prop, clicar num card do AK caía na
 * rota CM-only e devolvia 404 — bugfix 2026-08-08.
 */

import { AlertTriangle, FileText, Hash, Shield, Snowflake, Tag } from "lucide-react";
import { Link } from "@/lib/Link";
import type { NoteListItem } from "@/lib/types";
import type { Adapter } from "@/lib/api";
import { Badge } from "@/components/kg/Badge";
import { cn } from "@/lib/utils";
import { useTranslation } from "react-i18next";

export function NoteCard({
  note,
  onClick,
  className,
  adapter = "memory",
}: {
  note: NoteListItem;
  onClick?: () => void;
  className?: string;
  adapter?: Adapter;
}) {
  const { t } = useTranslation();
  const route =
    adapter === "acquire"
      ? ({ kind: "extracted-note", id: note.id } as const)
      : ({ kind: "note", id: note.id } as const);
  return (
    <Link
      to={route}
      onClick={onClick}
      className={cn(
        // 2026-08-08 refactor: borda um pouco mais saturada no hover,
        // accent mais visível (75 vs 50), título maior e mais respiro.
        "block rounded-lg border border-border bg-card p-4 text-card-foreground transition-all hover:border-primary/30 hover:bg-accent/75 hover:shadow-sm",
        className,
      )}
    >
      <div className="flex items-start gap-3">
        <FileText className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground" aria-hidden />
        <div className="min-w-0 flex-1">
          <h3 className="truncate text-sm font-medium leading-snug">
            {note.title ?? note.id}
          </h3>
          <div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
            {note.type && <Badge variant="outline">{note.type}</Badge>}
            <span className="flex items-center gap-1">
              <Hash className="h-3 w-3" aria-hidden />
              <span className="font-mono">{note.id}</span>
            </span>
            {/* P11: sinalização passiva — o humano vê o estado da nota na
                lista, sem precisar abrir cada uma. */}
            {note.protected ? (
              <Badge variant="default" title={t("notes.protected.description")}>
                <Shield className="mr-1 h-2.5 w-2.5" aria-hidden />
                {t("notes.protected.label")}
              </Badge>
            ) : null}
            {note.lifecycle === "cold" ? (
              <Badge variant="outline" title={t("notes.lifecycle.coldDescription")}>
                <Snowflake className="mr-1 h-2.5 w-2.5" aria-hidden />
                {t("notes.lifecycle.cold")}
              </Badge>
            ) : null}
            {(note.pending_review_count ?? 0) > 0 ? (
              <Badge variant="destructive">
                <AlertTriangle className="mr-1 h-2.5 w-2.5" aria-hidden />
                {t("notes.review.pendingCount", { count: note.pending_review_count })}
              </Badge>
            ) : null}
          </div>
          {note.tags && note.tags.length > 0 ? (
            <div className="mt-2 flex flex-wrap gap-1">
              {note.tags.map((tag) => (
                <Badge key={tag} variant="secondary" className="text-[10px]">
                  <Tag className="mr-1 h-2.5 w-2.5" aria-hidden />
                  {tag}
                </Badge>
              ))}
            </div>
          ) : null}
        </div>
      </div>
    </Link>
  );
}
