/**
 * Hash-based routing manual — sem React Router.
 *
 * Patter idêntico ao ``readShellRoute``/``writeShellRoute`` da WebUI
 * (App.tsx). Suporta:
 *
 *   ``#``                    → home
 *   ``#/notes``              → listagem de notas (CM)
 *   ``#/notes/:id``          → visualização de nota CM
 *   ``#/notes/:id/edit``     → editor de nota CM
 *   ``#/extracted``          → listagem de notas extraídas (AK)
 *   ``#/extracted-notes/:id`` → visualização de nota AK
 *   ``#/extracted-notes/:id/edit`` → editor de nota AK
 *   ``#/sources``            → listagem de Sources
 *   ``#/sources/:id``        → visualização de Source
 *   ``#/graph``              → grafo
 *   ``#/search?q=...``       → search
 *   ``#/stats``              → stats
 *
 * O estado fica no ``window.location.hash``; ``subscribe`` propaga via
 * ``hashchange`` events.
 */

export type RouteKind =
  | "home"
  | "notes"
  | "note"
  | "note-edit"
  | "extracted"
  | "extracted-note"
  | "extracted-note-edit"
  | "sources"
  | "source"
  | "graph"
  | "search"
  | "stats"
  | "notFound";

export interface Route {
  kind: RouteKind;
  id?: string;
  query?: URLSearchParams;
  /** Path original (sem ``#``) quando ``kind === "notFound"``. */
  raw?: string;
}

const DEFAULT_ROUTE: Route = { kind: "home", query: new URLSearchParams() };

export function parseHash(rawHash: string): Route {
  let hash = rawHash;
  if (hash.startsWith("#")) hash = hash.slice(1);
  if (!hash || hash === "/") return { ...DEFAULT_ROUTE };
  const [path, queryRaw = ""] = hash.split("?", 2);
  const query = new URLSearchParams(queryRaw);
  // Helper local: decoding defensivo. ``decodeURIComponent`` pode
  // levantar ``URIError`` quando o input tem sequência de bytes
  // malformada (ex.: ``%E0%A4%A`` — UTF-8 incompleto). Bug SPA-R2-3
  // (revisão 2): no ``useHashRoute`` o handler de ``hashchange``
  // chamava ``readRoute()`` que explodia o handler inteiro — rota
  // ficava congelada, sem fallback para home. Aqui capturamos e
  // usamos a string RAW como id, garantindo que a navegação nunca
  // quebra (UI pode mostrar um id feio, mas não trava).
  const safeDecode = (s: string): string => {
    try {
      return decodeURIComponent(s);
    } catch {
      return s;
    }
  };
  if (path === "/notes") return { kind: "notes", query };
  if (path === "/extracted") return { kind: "extracted", query };
  if (path === "/sources") return { kind: "sources", query };
  if (path === "/graph") return { kind: "graph", query };
  if (path === "/stats") return { kind: "stats", query };
  if (path === "/search") return { kind: "search", query };
  if (path.startsWith("/notes/")) {
    const rest = path.slice("/notes/".length);
    if (rest.endsWith("/edit")) {
      const id = safeDecode(rest.slice(0, -"/edit".length));
      return { kind: "note-edit", id, query };
    }
    const id = safeDecode(rest);
    return { kind: "note", id, query };
  }
  // Rotas dedicadas para notas do AK (extracted-notes/:id) — bugfix
  // 2026-08-08: notas do AK ficavam órfãs porque o NoteCard apontava
  // sempre para ``#/notes/:id`` (rota CM-only), o NoteView batia no
  // CM via adapter "memory" e devolvia 404 → "Erro de rede". Agora
  // notas AK têm sua própria rota, mantendo o read-side read-only do
  // plano-mestre v2.4 §C17 (cross-bundle edits continuam bloqueados).
  if (path.startsWith("/extracted-notes/")) {
    const rest = path.slice("/extracted-notes/".length);
    if (rest.endsWith("/edit")) {
      const id = safeDecode(rest.slice(0, -"/edit".length));
      return { kind: "extracted-note-edit", id, query };
    }
    const id = safeDecode(rest);
    return { kind: "extracted-note", id, query };
  }
  if (path.startsWith("/sources/")) {
    const id = safeDecode(path.slice("/sources/".length));
    return { kind: "source", id, query };
  }
  // M10 (bugfix-spa-2026-08-02): qualquer path desconhecido caía em
  // ``DEFAULT_ROUTE`` — incluindo ``#/new``, que a UI oferece como
  // deep-link de "criar nota". O humano clicava, a URL continuava
  // ``#/new`` e a Home aparecia: parecia que a página tinha carregado e
  // simplesmente não fazia nada. Rota desconhecida agora é 404 explícito.
  return { kind: "notFound", raw: path, query };
}

export function readRoute(): Route {
  if (typeof window === "undefined") return { ...DEFAULT_ROUTE };
  return parseHash(window.location.hash);
}

export function buildHash(route: Route): string {
  const query = (route.query ?? new URLSearchParams()).toString();
  const suffix = query ? `?${query}` : "";
  switch (route.kind) {
    case "home":
      return "#/";
    case "notes":
      return `#/notes${suffix}`;
    case "note":
      return `#/notes/${encodeURIComponent(route.id ?? "")}${suffix}`;
    case "note-edit":
      return `#/notes/${encodeURIComponent(route.id ?? "")}/edit${suffix}`;
    case "extracted":
      return `#/extracted${suffix}`;
    case "extracted-note":
      return `#/extracted-notes/${encodeURIComponent(route.id ?? "")}${suffix}`;
    case "extracted-note-edit":
      return `#/extracted-notes/${encodeURIComponent(route.id ?? "")}/edit${suffix}`;
    case "sources":
      return `#/sources${suffix}`;
    case "source":
      return `#/sources/${encodeURIComponent(route.id ?? "")}${suffix}`;
    case "graph":
      return `#/graph${suffix}`;
    case "stats":
      return `#/stats${suffix}`;
    case "search":
      return `#/search${suffix}`;
    case "notFound":
      // Round-trip: preserva o path que o humano digitou, para que a URL
      // continue mostrando ``#/new`` enquanto a view de 404 explica o que
      // aconteceu (em vez de reescrever a barra de endereços por baixo).
      return `#${route.raw ?? "/"}${suffix}`;
  }
}

export function writeRoute(route: Route, options: { replace?: boolean } = {}): void {
  if (typeof window === "undefined") return;
  const next = buildHash(route);
  if (window.location.hash === next) return;
  if (options.replace) {
    window.history.replaceState(
      null,
      "",
      `${window.location.pathname}${window.location.search}${next}`,
    );
    return;
  }
  window.location.hash = next;
}

export function isSameRoute(a: Route, b: Route): boolean {
  const aq = (a.query ?? new URLSearchParams()).toString();
  const bq = (b.query ?? new URLSearchParams()).toString();
  return a.kind === b.kind && a.id === b.id && aq === bq;
}
