/**
 * ``NoteEditor`` — editor markdown com CAS (D47 do P6).
 *
 * Fase 2 do refactor plan: textarea+preview lado-a-lado (DC-S4) +
 * ConflictResolver 3-vias (B3) quando o 409 vem com body estruturado.
 *
 * Detecta 409 (CAS conflict) via ApiError e parseia o body como
 * ``BodyConflict`` (Zod schema). Se válido, renderiza o
 * ``ConflictResolver`` com 2 painéis (Local vs Server) + opções
 * cancel/reload/merge/overwrite (overwrite só visível se
 * ``settings.advanced.allowOverwrite === "true"``).
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { Loader2, Save, X, Bold, Italic, Code, Link2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { NotePreview } from "@/components/kg/NotePreview";
import { ConflictResolver, type BodyConflict } from "@/components/kg/ConflictResolver";
import { ApiError } from "@/lib/api";
import { z } from "zod";
import type { NoteReadResponse } from "@/lib/types";
import { cn } from "@/lib/utils";

/** Schema do body do 409 — alinha com o backend CM. */
const BodyConflictSchema = z.object({
  status: z.literal("conflict"),
  base_body_hash: z.string(),
  current_body_hash: z.string(),
  server_body: z.string(),
});

export function NoteEditor({
  note,
  onSave,
  onCancel,
  onSaved,
  onReload,
}: {
  note: NoteReadResponse;
  onSave: (next: { body: string; baseBodyHash: string }) => Promise<unknown>;
  onCancel: () => void;
  onSaved: () => void;
  /** Chamado quando o humano escolhe "recarregar" no dialog de CAS. */
  onReload: () => void | Promise<void>;
}) {
  const { t } = useTranslation();
  const [body, setBody] = useState(note.body);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [conflict, setConflict] = useState<BodyConflict | null>(null);
  const [conflictLocal, setConflictLocal] = useState<string>("");
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  // M12 (bugfix-spa-2026-08-02): este effect resetava ``body`` sempre que
  // ``note.body`` mudasse. Como ``note`` é re-fetchado pelo pai, uma
  // escrita externa na mesma nota (outro agente, outro dispositivo, o
  // próprio pipeline do CM) trocava ``note.body`` no meio da digitação e
  // as edições NÃO SALVAS do humano desapareciam sem aviso.
  //
  // Regras agora:
  //  - ``note.id`` mudou  → navegação para outra nota: reseta sempre.
  //  - mesma nota, body do servidor igual ao anterior → nada a fazer.
  //  - mesma nota, body do servidor mudou → só aceita se o humano não
  //    tiver editado (``current === prev.body``); caso contrário mantém
  //    o buffer local e deixa o CAS/409 resolver no save.
  const lastNotePropRef = useRef<{ id: string; body: string }>({
    id: note.id,
    body: note.body,
  });

  useEffect(() => {
    const prev = lastNotePropRef.current;
    lastNotePropRef.current = { id: note.id, body: note.body };

    if (prev.id !== note.id) {
      setBody(note.body);
      setError(null);
      setConflict(null);
      return;
    }
    if (prev.body === note.body) return;
    // ``setBody`` funcional: lê o buffer atual sem precisar de ``body``
    // nas deps (que faria o effect rodar a cada tecla digitada).
    setBody((current) => (current === prev.body ? note.body : current));
  }, [note.id, note.body]);

  const dirty = body !== note.body;

  const doSave = useCallback(
    async (overrideBody?: string, overrideBaseHash?: string) => {
      setSaving(true);
      setError(null);
      try {
        await onSave({
          body: overrideBody ?? body,
          baseBodyHash: overrideBaseHash ?? note.body_hash,
        });
        onSaved();
        // B4 (auditoria 2026-07-31): sucesso → limpa o conflict state
        // para desmontar o ConflictResolver. Importante: isto
        // só roda se ``onSave`` não jogou exceção. Se jogou (rede,
        // 500, outro 409), o conflict fica setado e o dialog
        // permanece aberto com o server_body atualizado.
        setConflict(null);
      } catch (e) {
        if (e instanceof ApiError && e.status === 409) {
          // Outro 409 (alguém sobrescreveu durante o merge). Atualiza
          // o conflict com o NOVO server_body, e re-throw para o
          // ConflictResolver manter o dialog aberto.
          const detail = (e as ApiError & { detail?: unknown }).detail;
          const parsed = BodyConflictSchema.safeParse(detail);
          if (parsed.success) {
            setConflict(parsed.data);
            setConflictLocal(overrideBody ?? body);
          } else {
            setConflict({
              status: "conflict",
              base_body_hash: note.body_hash,
              current_body_hash: "",
              server_body: "",
            });
            setConflictLocal(overrideBody ?? body);
          }
          throw e;
        }
        // Erro não-409 (rede, 500, etc.). Re-throw para o
        // ConflictResolver mostrar erro inline e permitir retry/cancel.
        setError(e instanceof Error ? e.message : String(e));
        throw e;
      } finally {
        setSaving(false);
      }
    },
    [body, note.body_hash, onSave, onSaved],
  );
  // Bug fix (revisão 2026-07-31): ``doSave`` sempre re-lança o erro
  // (propositalmente — é o contrato que ``ConflictResolver.onResolve``
  // depende para saber que o merge/overwrite falhou e manter o dialog
  // aberto). Os dois call sites diretos do botão "Save"/Ctrl+S abaixo
  // não têm ninguém aguardando essa promise, então sem ``.catch(() =>
  // {})`` o navegador reporta "Uncaught (in promise)" no console mesmo
  // já tendo tratado o erro via ``setError``/``setConflict`` acima —
  // ruído, não bug funcional, mas pode disparar falso-positivo em
  // ferramentas de report de erro no futuro.

  const handleReload = async () => {
    setConflict(null);
    await onReload();
  };

  const insertAround = useCallback((before: string, after: string) => {
    const ta = textareaRef.current;
    if (!ta) return;
    const start = ta.selectionStart ?? 0;
    const end = ta.selectionEnd ?? 0;
    const selected = body.slice(start, end);
    const next = body.slice(0, start) + before + selected + after + body.slice(end);
    setBody(next);
    // Restaura seleção dentro do inserted text.
    // N6 (auditoria #2, 2026-07-31): guarda o handle do rAF e
    // checa ``textareaRef.current`` dentro do callback — se o
    // componente desmontar entre o ``setBody`` e o próximo frame,
    // ``ta`` (capturado localmente) ainda existe como referência
    // DOM, mas ``focus()`` e ``setSelectionRange`` podem lançar se o
    // textarea já foi detachado do DOM. Checar via ref atual é mais
    // seguro que confiar na captura local.
    const rafId = requestAnimationFrame(() => {
      const current = textareaRef.current;
      if (!current) return; // unmount — aborta silenciosamente
      current.focus();
      const cursor = start + before.length + selected.length + after.length;
      current.setSelectionRange(cursor, cursor);
    });
    // Cleanup opcional: ``insertAround`` é chamado por botão (evento
    // síncrono), não há effect para retornar cleanup. O rAF é
    // fire-once, não acumula — único risco é unmount antes do frame.
    // A checagem via ``textareaRef.current`` acima é suficiente.
    void rafId;
  }, [body]);

  return (
    <div className="flex h-full flex-col gap-3">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-medium text-muted-foreground">
          {t("notes.editor.title", { id: note.id })}
        </h2>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" onClick={onCancel} disabled={saving}>
            <X className="mr-1 h-3.5 w-3.5" />
            {t("notes.actions.cancel")}
          </Button>
          <Button size="sm" onClick={() => void doSave().catch(() => {})} disabled={!dirty || saving}>
            {saving ? <Loader2 className="mr-1 h-3.5 w-3.5 animate-spin" /> : <Save className="mr-1 h-3.5 w-3.5" />}
            {t("notes.actions.save")}
          </Button>
        </div>
      </div>

      <div className="flex items-center gap-1">
        <Button type="button" variant="ghost" size="sm" onClick={() => insertAround("**", "**")} disabled={saving}>
          <Bold className="h-3.5 w-3.5" />
        </Button>
        <Button type="button" variant="ghost" size="sm" onClick={() => insertAround("*", "*")} disabled={saving}>
          <Italic className="h-3.5 w-3.5" />
        </Button>
        <Button type="button" variant="ghost" size="sm" onClick={() => insertAround("`", "`")} disabled={saving}>
          <Code className="h-3.5 w-3.5" />
        </Button>
        <Button type="button" variant="ghost" size="sm" onClick={() => insertAround("[", "](https://)")} disabled={saving}>
          <Link2 className="h-3.5 w-3.5" />
        </Button>
      </div>

      <div className={cn("grid min-h-0 flex-1 grid-cols-1 gap-3 md:grid-cols-2")}>
        <Textarea
          ref={textareaRef}
          className="h-full resize-none font-mono text-sm"
          value={body}
          onChange={(e) => setBody(e.target.value)}
          placeholder={t("notes.editor.placeholder")}
          disabled={saving}
          onKeyDown={(e) => {
            if ((e.ctrlKey || e.metaKey) && e.key === "s") {
              e.preventDefault();
              if (dirty && !saving) void doSave().catch(() => {});
            }
          }}
        />
        <div className="h-full overflow-auto rounded-md border border-border bg-card p-3">
          <NotePreview body={body} />
        </div>
      </div>

      {error ? <p className="text-xs text-destructive">{error}</p> : null}

      {conflict && (
        <ConflictResolver
          conflict={conflict}
          localBody={conflictLocal}
          open={true}
          onResolve={async (merged) => {
            // Merge ou overwrite: salva com baseBodyHash do servidor
            // (que já conhecemos via conflict.current_body_hash). Se o
            // servidor mandou server_body vazio (fallback 409 cru),
            // usamos o base_body_hash original.
            //
            // B4 (auditoria 2026-07-31): ``doSave`` é awaited aqui e
            // re-throws se falhar — ConflictResolver captura o erro e
            // mantém o dialog aberto para o humano tentar de novo.
            // Não chamamos ``setConflict(null)`` antes — o Conflict
            // desmonta sozinho quando ``onResolve`` resolve com
            // sucesso (a próxima vez que ``conflict`` vira ``null``).
            const baseToUse =
              conflict.current_body_hash || conflict.base_body_hash || note.body_hash;
            await doSave(merged, baseToUse);
          }}
          onCancel={() => setConflict(null)}
          onReload={handleReload}
        />
      )}
    </div>
  );
}